import {clsx} from 'clsx'

import type {MarketingHeaderProps} from './marketing-header.types'
import styles from './MarketingHeader.module.css'

/**
 * Composer for the marketing (logged-out) header, rendered from Rails via
 * `render_react_partial name: "marketing-header"` behind the `site_marketing_header_react` flag.
 *
 * W1 (#233) is an enabler: it registers the partial and renders an SSR-safe header root with
 * `data-color-mode` parity. The discrete pieces are added by later workstreams (see TODO regions):
 * the class-parity shell + mobile behavior + composed navigation in W2, logo + auth CTAs in W3,
 * logged-out search in W4. No interactive markup is rendered yet, so the existing global header JS
 * has nothing to fight and there is no hidden-interactive-element a11y concern.
 */
export function MarketingHeader(props: MarketingHeaderProps) {
  const {color_mode = 'auto'} = props

  return (
    <header
      className={clsx(styles.root, 'HeaderMktg')}
      role="banner"
      data-color-mode={color_mode}
      data-light-theme="light"
      data-dark-theme="dark"
    >
      {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
      <h2 className="sr-only">Navigation Menu</h2>
      {/* TODO(W2): class-parity shell (HeaderMktg backdrop/hamburger/focus-trap, js-details-* classes) + mobile behavior via global header.ts + compose <MarketingNavigation> */}
      {/* TODO(W3): GitHub logo (home_path), auth CTAs (login_path/signup_path), appearance settings */}
      {/* TODO(W4): logged-out search (quick-search) */}
    </header>
  )
}
